local Speak = Speak or {}
Speak.SpeakTypeDefine = {}
Speak.Cfg = Speak.Cfg or {}
Speak.Group = Speak.Group or {}

Speak.SpeakTypeDefine =
{
    CHAT = 0,                   --普通喊话
    TIP = 1,                    --提示
    STORY = 2,                  --剧情(全屏界面)
    CALLBOARD = 3,              --跑马灯
    FLASHTIP = 4,               --flashtip
    BROADCAST = 5,              --用类似广播的方式喊
}

Speak.ServerDefine =
{
    Default = 0,
    CenterServer = 1,
    OneWorldCenterServer = 2,
}
    --showname = “<%= host.name %>”读取玩家的角色名，写其它内容则直接进行显示。不需要就填"
    --showimage = “pathID”，不需要就填"
    --frametype = 0为左显示界面，1为右显示界面
    --server = 0 --表示源服和中心服，2表示跨地区（跨版本）中心服 ，不配置默认是 0

