Speak.Cfg[1983] =
{
    Content =
    {
        [1] = 
        {
             text = "　　兄弟們放心，那位大人說了，只要咱們老老實實替他幹活，將來吃香的喝辣的！",
             showname    ="叛亂首領",
             showimage   = "1420",
             frametype   = "right",
        },

        [2] = 
        {
             text = "　　首……兀突骨雖然嚴厲了些，但對待手下十分慷慨，我們貿然離開，還真有些於心不忍。",
             showname    ="叛亂藤甲軍",
             showimage   = "709",
             frametype   = "left",
        },

        [3] = 
        {
             text = "　　大家都是一路來的兄弟，你說的我能理解，但是兀突骨死守秘方，是不會把藤甲和我們烏戈國發揚廣大的，只有那位大人才能帶領烏戈國一統南蠻！",
             showname    ="叛亂首領",
             showimage   = "1420",
             frametype   = "right",
        },

    },
    channel     = 6,
    period      = 5000,
    repeattime  = 1,
    priority    = 0,
    showinchat  = false,
    effect      = 0,
    showuitype  = Speak.SpeakTypeDefine.STORY,
    server      = Speak.ServerDefine.Default,
 }

Speak.Cfg[1984] =
{
    Content =
    {
        [1] = 
        {
             text = "　　他本是我最信任的領兵俘長，眾將士也十分最尊敬，萬萬想不到……",
             showname    ="兀突骨",
             showimage   = "709",
             frametype   = "left",
        },

        [2] = 
        {
             text = "　　這次多謝你出手相助，叛徒之事我會處理，烏戈國的醜事竟然讓外人看了去，你走吧，我今後不會再去找祝融夫人的麻煩。如果你有難了，可以隨時來找我。",
             showname    ="兀突骨",
             showimage   = "709",
             frametype   = "left",
        },

    },
