Speak.Cfg[1986] =
{
    Content =
    {
        [1] = 
        {
             text = "　　我此番前來一是祝賀，二是想向大王獻上賀詞，但自古忠言多逆耳，不知當講不當講。",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
