Speak.Cfg[2380] =
{
    Content =
    {
        [1] = 
        {
             text = "　　這是……孔明，還有大英雄<%= host.name %>，你們能來看望老夫，老夫已經深感欣慰，竟然還帶了這樣貴重的禮物，老夫擔待不起啊！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [2] = 
        {
             text = "　　先生言重了。回來拜訪師長是晚輩應當做的，畢竟一日為師，終生為父！啟蒙之恩一言難盡，我與孔明正期盼能與恩師一起喝杯茶，敘敘舊。",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "right",
        },

        [3] = 
        {
             text = "　　這……這時候正趕上小孩子們課間休息，院中吵鬧，孔明與英雄不如隨老夫前往山上，在涼亭中共賞山景，飲茶談天，二位意下如何？",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [4] = 
        {
             text = "　　先生，您面色凝重，是不是書院中發生了什麼事？如果有我能幫忙的地方，您儘管說就是了！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "right",
        },

        [5] = 
        {
             text = "　　唉……事到如今也不能再隱瞞了。我的書院裡有個學生，名叫思勤。這個孩子天生聰慧過人，卻也頑劣成性。就在前兩天，他不滿意我為他們佈置的課業，竟然偷跑去學了黃巾軍的妖術，在學堂裡擺起陣來！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [6] = 
        {
             text = "　　黃巾軍淨是些傷敵一千、自損八百的妖術邪法，被一個孩子學了去，豈不是危險萬分？",
             showname    ="諸葛亮",
             showimage   = "1423",
             frametype   = "right",
        },

        [7] = 
        {
             text = "　　這不必擔心，我看過那妖陣，不過是小孩子把戲，倒不危險，只是需要近施術者的身才能破解，但那迷陣不知用了什麼詭計，偌大一個書院無人解得了此陣。",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [8] = 
        {
             text = "　　在那孽徒正在講臺上撒潑，拿著同學的課業揚言說要佔領書院，這樣就永遠不用做日課了！這成何體統！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [9] = 
        {
             text = "　　[ff0000]（你壓低了聲音對孔明說）[-]\n　　當年我都沒敢幹的事情，竟然給這小孩兒做成了，是塊幹大事的料啊！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [10] = 
        {
             text = "　　[ff0000]（諸葛亮眼神示意你不要再說下去了）[-]",
             showname    ="諸葛亮",
             showimage   = "1423",
             frametype   = "right",
        },

        [11] = 
        {
             text = "　　[ff0000]（水鏡先生氣得鬍子都吹了起來）[-]\n　　英雄莫要說笑！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [12] = 
        {
             text = "　　不不不！您誤會了！我的意思是，這樣確實不對！\n　　請您放心，我會協助您破解書院中的妖陣，好好教育教育那個孩子的！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "right",
        },

        [13] = 
        {
             text = "　　唉……算了。那就有勞英雄了，妖陣兇險，請您務必儘快救出他！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

    },
    channel     = 6,
    period      = 5000,
    repeattime  = 1,
    priority    = 0,
    showinchat  = false,
    effect      = 0,
    showuitype  = Speak.SpeakTypeDefine.STORY,
    server      = Speak.ServerDefine.Default,
 }

Speak.Cfg[2381] =
{
    Content =
    {
        [1] = 
        {
             text = "　　[ff0000]（思勤梗著脖子，毫不示弱）[-]\n　　我才沒錯！是先生錯了！",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [2] = 
        {
             text = "　　你……！你倒是說說你為什麼要擾亂課堂秩序！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [3] = 
        {
             text = "　　您看，您在別的事情上都非常隨意，甚至都被別人叫成好好先生！為什麼卻要在安排那麼多課業？您都要把大家壓得喘不過氣來了！",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [4] = 
        {
             text = "　　你懂什麼，想要滿腹經綸，就得付出同等分量的努力，你不是說自己長大了以後要當英雄和孔明那樣的國家棟樑嗎？",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [5] = 
        {
             text = "　　那也不能強迫已經熟知這些知識的同學們再去進行沒有意義的重複練習呀！",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [6] = 
        {
             text = "　　[ff0000]水鏡先生看起來有些遲疑了。[-]\n　　這……好，好，老夫想一想……是課業使你們感到疲憊了嗎？",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [7] = 
        {
             text = "　　原來事情是這樣，亮有一計可解此困境，只是恐怕要先生多些操勞。",
             showname    ="諸葛亮",
             showimage   = "1423",
             frametype   = "right",
        },

        [8] = 
        {
             text = "　　但說無妨。",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [9] = 
        {
             text = "　　先生和不給學生一些測驗，便可悉知學生對知識的熟悉程度，若是已掌握的，就不要再讓他們多做些無用功，學生也能輕鬆一些，豈不兩全其美。",
             showname    ="諸葛亮",
             showimage   = "1423",
             frametype   = "right",
        },

        [10] = 
        {
             text = "　　這，我……唉……孔明所言極是，是我墨守成規了。思勤，你先回去，告訴同學們，一會兒準備考試。",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [11] = 
        {
             text = "　　啊——？",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [12] = 
        {
             text = "　　噗……到底逃不過考試的命運啊。",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [13] = 
        {
             text = "　　還不快去！",
             showname    ="水鏡先生",
             showimage   = "1422",
             frametype   = "left",
        },

        [14] = 
        {
             text = "　　我還想和英雄多玩一會兒呢！",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [15] = 
        {
             text = "　　你這個聰明腦瓜倒是貪玩！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [16] = 
        {
             text = "　　那當然了，和你玩可比死讀書有趣多了！英雄，如果你願意來和我玩，我還會給你準備禮物！",
             showname    ="思勤",
             showimage   = "8428",
             frametype   = "right",
        },

        [17] = 
        {
             text = "　　好吧，我答應你。但是現在你得先回去，好好學習，準備應付考試吧！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

    },
    channel     = 6,
    period      = 5000,
    repeattime  = 1,
    priority    = 0,
    showinchat  = false,
    effect      = 0,
    showuitype  = Speak.SpeakTypeDefine.STORY,
    server      = Speak.ServerDefine.Default,
 }

