Speak.Cfg[2419] =
{
    Content =
    {
        [1] = 
        {
             text = "　　你就是那個正在找我的西域商人？",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [2] = 
        {
             text = "　　正是奴家。奴家名叫段瑢，自西域而來，帶著滿滿一駝隊的稀奇貨物，想在中原售賣，賺些薄利。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [3] = 
        {
             text = "　　只可惜小店才新開業，無人知曉。所以奴家想舉行推廣活動，若是將軍這樣美名遠揚的英才願意來幫幫忙，那一定會人氣飛漲，到時奴家必有好禮相送。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [4] = 
        {
             text = "　　說白了不就是想讓我跑腿麼……你先說說看是什麼活計，有什麼報酬，說清楚了我再考慮要不要幫你。",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [5] = 
        {
             text = "　　將軍倒是心直口快呢，不過正好，明明白白的才好做生意不是？不過在這之前，奴家要問將軍，您可知道“秋神節”嗎？",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [6] = 
        {
             text = "　　秋神？沒聽說過，我們這兒可沒有這路神仙。",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [7] = 
        {
             text = "　　將軍您別急嘛。秋神是西域掌管商業和姻緣的神明，每年深秋時節，奴家的家鄉都會舉行祭祀秋神的典禮。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [8] = 
        {
             text = "　　像將軍您這樣的年輕人們不論單身與否，都會參加祭典上舉行“抽葉簽”活動，體現自己的魅力，並與他人結緣，積累緣分。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [9] = 
        {
             text = "　　抽葉簽？是抽獎嗎？",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [10] = 
        {
             text = "　　並不是那麼簡單哦。葉簽上寫著六種不同的美德，對應六種不同的任務。在祭典期間，參與的人兒每天都可以抽一次葉簽，葉簽上寫的任務需得在太陽落山之前完成，這樣才能得到秋神的祝福。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [11] = 
        {
             text = "　　所以奴家想在中原也舉辦一次秋神節，既可以宣傳奴家家鄉的文化，也可以為小店積攢些人氣。所以宣傳活動的話，奴家也想請將軍來試試“抽葉簽”。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [12] = 
        {
             text = "　　將軍在每次完成任務，為奴家宣傳小店，奴家就會為將軍記上一筆“貢獻度”。等到攢夠一定數量了，奴家就會將為將軍準備的禮物雙手奉上。您看，這是禮物的清單……",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [13] = 
        {
             text = "　　我看看……你這報酬雖然好，但是有點少啊？",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [14] = 
        {
             text = "　　呵呵呵……畢竟是為店面宣傳，當然人越多越好不是？所以考慮到其他的參與者，奴家舉行了一個競賽，如果將軍想要更多的報酬，就請努力和其他的參與者展開競爭吧？",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [15] = 
        {
             text = "　　我就知道沒這麼簡單……",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

        [16] = 
        {
             text = "　　呵呵呵……另外，本店出售的商品也對將軍打折出售哦，如果您買了，用得好，那就是對小店最大的宣傳了，奴家也會為您算一筆貢獻度哦。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [17] = 
        {
             text = "　　也行吧，報酬裡倒是有幾件我看上的東西。不過，多說不如多做，就讓我先來試試看你說的“抽葉簽”吧！",
             showname    ="<%= host.name %>",
             showimage   = "<%= host.portrait %>",
             frametype   = "left",
        },

    },
    channel     = 6,
    period      = 5000,
    repeattime  = 1,
    priority    = 0,
    showinchat  = false,
    effect      = 0,
    showuitype  = Speak.SpeakTypeDefine.STORY,
    server      = Speak.ServerDefine.Default,
 }

Speak.Cfg[2420] =
{
    Content =
    {
        [1] = 
        {
             text = "　　這裡有兩種籤筒，“修身養性”裡的葉簽任務比較平和，“征戰四方”則更側重武藝，將軍可以根據自己的喜好進行選擇。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
        },

        [2] = 
        {
             text = "　　另外，雖然任務不盡相同，但[ff0000]獲得的貢獻度都是一樣的[-]哦，所以呢，請將軍不要有顧慮，隨心挑選即可。",
             showname    ="段瑢",
             showimage   = "8522",
             frametype   = "right",
